<?php declare(strict_types=1); namespace Database\Schema; use Core\Database\Schema\Blueprint; use Core\Database\Schema\SchemaDefinition; class NotificationsSchema extends SchemaDefinition { protected string $table = 'notifications'; public function define(Blueprint $table): void { $table->id(); $table->foreignId('user_id'); $table->string_50('type')->default('info'); $table->string_255('title'); $table->long_text('body'); $table->json('data')->nullable(); $table->dateTime('read_at')->nullable(); $table->timestamps(); $table->foreign('user_id')->references('id')->on('users')->onDelete('CASCADE'); } } 